import random, time
from matrix_ops import count_pairs_within

def naive(points, r):
    count=0; r2=r*r
    for i,(x,y) in enumerate(points):
        for j in range(i+1,len(points)):
            dx=points[j][0]-x; dy=points[j][1]-y
            if dx*dx+dy*dy <= r2: count += 1
    return count

rng=random.Random(12345)
configs=[('uniform',3400,.3),('clustered',2600,.7),('gridded',2200,.8)]
for kind,n,r in configs:
    if kind=='uniform': pts=[(rng.random()*100,rng.random()*100) for _ in range(n)]
    elif kind=='clustered':
        centers=[(rng.random()*10,rng.random()*10) for _ in range(5)]
        pts=[(centers[i%5][0]+rng.gauss(0,.15),centers[i%5][1]+rng.gauss(0,.15)) for i in range(n)]
    else:
        side=int(n**.5); pts=[(float(i%side),float(i//side)) for i in range(side*side)]
    t=time.perf_counter(); expected=naive(pts,r); old=time.perf_counter()-t
    t=time.perf_counter(); actual=count_pairs_within(pts,r); new=time.perf_counter()-t
    print(f'{kind}: {expected=} {actual=} old={old:.4f}s new={new:.4f}s speedup={old/new:.1f}x')

# Random differential testing, including negative and zero radii.
for n in range(0, 35):
    for _ in range(100):
        pts=[(rng.uniform(-5,5),rng.uniform(-5,5)) for _ in range(n)]
        if n and rng.random() < .2: pts += [pts[rng.randrange(n)]] * rng.randrange(1,4)
        r=rng.choice([0.0, -0.0, .1, .7, -1.3, 10.0])
        a=naive(pts,r); b=count_pairs_within(pts,r)
        assert a == b, (pts,r,a,b)
print('random differential checks: ok')
